SELECT c.customer_name
FROM customers c
JOIN first_notification_of_loss f ON c.customer_id = f.customer_id
WHERE f.service_id IN (
    SELECT service_id FROM services WHERE service_name = 'Close a policy'
)
AND f.service_id IN (
    SELECT service_id FROM services WHERE service_name = 'New policy application'
);

SELECT DISTINCT m.name, m.trade_name
FROM medicine m
JOIN medicine_enzyme_interaction mei ON m.id = mei.medicine_id;

SELECT ms.Season, ms.Player, c.Country_name 
FROM match_season ms
JOIN country c ON ms.Country = c.Country_name;

SELECT ms.Season, ms.Player, t.Name 
FROM match_season ms
JOIN team t ON ms.Team = t.Team_id;

SELECT cr.source_system_code, cr.master_customer_id
FROM CMI_Cross_References cr
JOIN Parking_Fines pf ON cr.cmi_cross_ref_id = pf.cmi_cross_ref_id;

SELECT e.Delegate, c.County_name 
FROM election e
JOIN county c ON e.District = c.County_id;

SELECT DISTINCT cl.brand
FROM photos p
JOIN camera_lens cl ON p.camera_lens_id = cl.id
WHERE p.mountain_id IN (
    SELECT id FROM mountain WHERE range = 'Toubkal Atlas'
)
AND p.mountain_id IN (
    SELECT id FROM mountain WHERE range = 'Lasta Massif'
);

SELECT S.Fname, S.LName, E.Grade 
FROM STUDENT S 
JOIN ENROLLED_IN E ON S.StuID = E.StuID;

SELECT t.thing_id, t.type_of_Thing_Code, o.organization_details 
FROM Things t 
JOIN Organizations o ON t.organization_id = o.organization_id;

SELECT p.product_name
FROM product p
JOIN problems pr ON p.product_id = pr.product_id
WHERE pr.reported_by_staff_id IN (
    SELECT staff_id FROM staff WHERE staff_first_name = 'Lacey' AND staff_last_name = 'Bosco'
)
AND pr.reported_by_staff_id IN (
    SELECT staff_id FROM staff WHERE staff_first_name = 'Kenton' AND staff_last_name = 'Champlin'
);

SELECT ta.How_to_Get_There, ra.Royal_Family_Details
FROM TOURIST_ATTRACTIONS ta
JOIN ROYAL_FAMILY ra ON ta.Tourist_Attraction_ID = ra.Royal_Family_ID;

SELECT c.name, c.area, c.population
FROM country c
JOIN roller_coaster rc ON c.Country_ID = rc.Country_ID
WHERE rc.speed > (
    SELECT AVG(speed) FROM roller_coaster
);

SELECT s.statement_id, s.statement_details, a.account_details 
FROM Statements s
JOIN Accounts a ON s.statement_id = a.statement_id;
